# Generated by manage.py generate_test_cases.
"""Secured incoming invitation responses through the actual component endpoint."""

from unittest.mock import patch

from django.http import HttpResponse

from bloomerp.models.communication.calendar import CalendarEvent
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.communication.calendar_fixtures import SchedulingFixtures


class TestRespondComponent(SchedulingFixtures, BloomerpComponentTestCase):
    view_name = "components_calendar_respond"

    def extendedSetup(self) -> None:
        """Create an invitation indexed through the actual calendar email pipeline."""
        self.prepare_calendar()
        self.item = self.index_email(self.make_email())

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Check authentication, Inbox isolation, independent policy, and successful reply."""
        kwargs = {"item_id": self.item.pk}
        return [
            RequestScenario(
                name="Anonymous response requires login",
                method="POST",
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="Other user cannot address this email",
                method="POST",
                user=self.outsider,
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Inbox access without calendar policies is insufficient",
                method="POST",
                user=self.owner,
                view_kwargs=kwargs,
                data={"sequence": "0", "response_status": "accepted"},
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Response requires POST",
                user=self.actor,
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=405),
            ),
            RequestScenario(
                name="Permitted invited identity sends accepted reply",
                method="POST",
                user=self.actor,
                view_kwargs=kwargs,
                data={"sequence": "0", "response_status": "accepted"},
                prepare=self.patch_send,
                expected=ExpectedResult(response_validators=self.accepted_response),
            ),
            RequestScenario(
                name="Stale response form cannot respond to new revision",
                method="POST",
                user=self.actor,
                view_kwargs=kwargs,
                data={"sequence": "99", "response_status": "accepted"},
                prepare=self.patch_send,
                expected=ExpectedResult(
                    status_code=400, response_validators=self.no_send
                ),
            ),
        ]

    def patch_send(self, scenario: RequestScenario) -> None:
        """Mock only SMTP transmission while retaining policy and service logic."""
        send_patch = patch(
            "bloomerp.communication.calendar.outgoing._send",
            return_value="<reply@test>",
        )
        self.send = send_patch.start()
        self.addCleanup(send_patch.stop)

    def accepted_response(self, response: HttpResponse) -> bool:
        """Confirm the same participant is updated and exactly one reply is sent."""
        event = CalendarEvent.objects.get()
        return (
            self.send.call_count == 1
            and event.participants.get(email=self.account.email_address).response_status
            == "accepted"
        )

    def no_send(self, response: HttpResponse) -> bool:
        """Confirm revision mismatch produces no external side effect."""
        return not self.send.called
